var bool bVersusCharacterAuditComplete;
var string VersusProbeCharacterA;
var string VersusProbeCharacterB;

function InitGame

local Vector ProbeLocation;
local float RemainingCooldown;
local HPVersusPRI ProbeAPRI;
local HPVersusPRI ProbeBPRI;

Log("HPVersusMechanicsProbe START A=" $ string(A) $ " B=" $ string(B));
ProbeAPRI = HPVersusPRI(A.PlayerReplicationInfo);
ProbeBPRI = HPVersusPRI(B.PlayerReplicationInfo);
if (ProbeAPRI != None)
    VersusProbeCharacterA = ProbeAPRI.SelectedCharacter;
if (ProbeBPRI != None)
    VersusProbeCharacterB = ProbeBPRI.SelectedCharacter;
A.ServerSelectVersusSpell(1);

VersusProbeResult(!A.bVersusDead && A.Health == 100
    && !A.IsVersusSpeedBoosted(), "respawn-restores-clean-state");
ProbeAPRI = HPVersusPRI(A.PlayerReplicationInfo);
ProbeBPRI = HPVersusPRI(B.PlayerReplicationInfo);
VersusProbeResult(ProbeAPRI != None && ProbeBPRI != None
    && ProbeAPRI.SelectedCharacter ~= VersusProbeCharacterA
    && ProbeBPRI.SelectedCharacter ~= VersusProbeCharacterB
    && A.Mesh == class'HPVersusCharacterProfiles'.static.GetMesh(
        VersusProbeCharacterA)
    && B.Mesh == class'HPVersusCharacterProfiles'.static.GetMesh(
        VersusProbeCharacterB),
    "character-profile-survives-respawn");
B.ApplyVersusSpeedBoost(1.5, 10.0);
